#include <braurser/daemon/jobs/srcinfo.hpp>
#include <gtest/gtest.h>

namespace braurser::daemon::jobs {
namespace {
constexpr std::string_view split =
    "# Generated by makepkg\n"
    "pkgbase = widget\n"
    "\tpkgdesc = A split package\n"
    "\tpkgver = 1.2.3\n"
    "\tpkgrel = 4\n"
    "\tepoch = 2\n"
    "\tarch = x86_64\n"
    "\tarch = aarch64\n"
    "\tdepends = glibc>=2.40\n"
    "\tdepends_x86_64 = libx11\n"
    "\tdepends_aarch64 = libdrm\n"
    "\tmakedepends = cmake\n"
    "\tmakedepends_x86_64 = nasm\n"
    "\tcheckdepends = pytest\n"
    "\tsha256sums = SKIP\n"
    "\n"
    "pkgname = widget\n"
    "\tprovides = virtual-widget=2:1.2.3\n"
    "\n"
    "pkgname = widget-libs\n"
    "\tdepends = musl\n";

TEST(SrcInfo, SplitPackagesInheritOverrideArchitectureAndEpoch) {
    const auto info = parse_srcinfo(split, "x86_64");
    ASSERT_TRUE(info);
    EXPECT_EQ(info->pkgbase, "widget");
    ASSERT_EQ(info->packages.size(), 2U);
    const auto& main = info->packages[0];
    EXPECT_EQ(main.pkgver, "1.2.3");
    EXPECT_EQ(main.pkgrel, "4");
    EXPECT_EQ(main.epoch, "2");
    EXPECT_EQ(main.depends, (std::vector<std::string>{"glibc>=2.40", "libx11"}));
    EXPECT_EQ(main.makedepends, (std::vector<std::string>{"cmake", "nasm"}));
    EXPECT_EQ(main.provides, (std::vector<std::string>{"virtual-widget=2:1.2.3"}));
    EXPECT_EQ(info->packages[1].depends, (std::vector<std::string>{"musl", "libx11"}));
    const auto arm = parse_srcinfo(split, "aarch64");
    ASSERT_TRUE(arm);
    EXPECT_EQ(arm->packages[0].depends, (std::vector<std::string>{"glibc>=2.40", "libdrm"}));
    EXPECT_FALSE(parse_srcinfo(split, "i686"));
}

TEST(SrcInfo, RejectsMalformedAndExcessiveInputWithoutExecutingAnything) {
    for (const auto* text : {"pkgname = orphan\n", "pkgbase = bad/name\n", "pkgbase = widget\n depends = glibc\n",
                             "pkgbase = widget\n\tdepends = bad>=\n", "pkgbase = widget\n\tdepends = foo;touch\n",
                             "pkgbase = widget\n\tpkgver = 1\n\tpkgver = 2\n",
                             "pkgbase = widget\n\tepoch = -1\n", "pkgbase = widget\n\tarch = any\r\n"})
        EXPECT_FALSE(parse_srcinfo(text, "x86_64")) << text;
    EXPECT_FALSE(parse_srcinfo(std::string(256 * 1024 + 1, 'x'), "x86_64"));
    EXPECT_FALSE(parse_srcinfo(std::string(4097, '\n'), "x86_64"));
    auto duplicate = std::string(split) + "pkgname = widget\n";
    EXPECT_FALSE(parse_srcinfo(duplicate, "x86_64"));
    auto binary = std::string(split); binary.push_back('\0');
    EXPECT_FALSE(parse_srcinfo(binary, "x86_64"));
}

TEST(PkgInfo, ParsesIdentityAndRuntimeDependenciesWithoutExecutingMetadata) {
    const auto info = parse_pkginfo("# Generated by makepkg\npkgname = widget\npkgver = 2:1.2-3\narch = x86_64\n"
        "pkgdesc = Text = with separator\nbuilddate = 123\ndepend = glibc>=2.40\ndepend = libx11\n");
    ASSERT_TRUE(info);
    EXPECT_EQ(info->name, "widget");
    EXPECT_EQ(info->version, "2:1.2-3");
    EXPECT_EQ(info->arch, "x86_64");
    EXPECT_EQ(info->depends, (std::vector<std::string>{"glibc>=2.40", "libx11"}));
}

TEST(PkgInfo, RejectsMissingDuplicateMalformedBinaryAndExcessiveMetadata) {
    const std::string valid = "pkgname = widget\npkgver = 1-1\narch = any\n";
    for (const auto* extra : {"pkgname = widget\n", "pkgver = 1-1\n", "arch = any\n", "depend = foo>=\n",
                               "depend = foo;touch\n", "invalid line\n", "arch = any\r\n"})
        EXPECT_FALSE(parse_pkginfo(valid + extra)) << extra;
    EXPECT_FALSE(parse_pkginfo("pkgname = widget\narch = any\n"));
    EXPECT_FALSE(parse_pkginfo(valid + std::string(1, '\0')));
    EXPECT_FALSE(parse_pkginfo(std::string(256 * 1024 + 1, 'x')));
    EXPECT_FALSE(parse_pkginfo(valid + std::string(4096, '\n')));
    std::string excessive = valid;
    for (int index = 0; index < 257; ++index) excessive += "depend = foo\n";
    EXPECT_FALSE(parse_pkginfo(excessive));
}

TEST(SrcInfo, DependenciesUseArchVersionComparison) {
    for (const auto* text : {"glibc", "glibc<3", "glibc<=3", "glibc=3", "glibc>=3", "glibc>3", "widget>=2:1.0-1"})
        EXPECT_TRUE(parse_dependency(text)) << text;
    for (const auto* text : {"", "foo>==1", "foo!=1", "foo ", "foo>=", "foo>=1 2", "/foo"})
        EXPECT_FALSE(parse_dependency(text)) << text;
    const auto dependency = parse_dependency("widget>=2:1.0-1");
    ASSERT_TRUE(dependency);
    EXPECT_FALSE(satisfies_version("1:99-1", *dependency));
    EXPECT_TRUE(satisfies_version("2:1.0-2", *dependency));
    EXPECT_FALSE(satisfies_version("", *dependency));
}
}
}
